function taskHtml(t){return`<div class="task ${t.done?'done':''}"><input type="checkbox" ${t.done?'checked':''} onchange="App.toggleTask('${esc(t.key)}')"><div class="task-text"><strong>${esc(t.text)}</strong><div class="meta">${esc(t.recipe)} · ${t.batches} כפולות · ${fmt(t.qty,0)} שקיות · ${esc(t.customer)} ${t.time?'· '+esc(t.time):''}</div></div></div>`}
function renderDashboard(){
  const os=activeOrders(),ts=generatedTasks(),today=dayKey(new Date()),low=state.inventory.filter(i=>inventoryTotal(i)<=inventoryMinTotal(i)).length,up=os.slice().sort((a,b)=>a.dueAt.localeCompare(b.dueAt)).slice(0,5),todayTasks=ts.filter(t=>t.date===today&&!t.done),bags=os.reduce((sum,o)=>sum+(o.items||[]).reduce((a,i)=>a+Number(i.qty||0),0),0),heroMessage=heroMessageForSession();
  document.getElementById('view-dashboard').innerHTML=`<section class="hero"><div class="hero-copy"><div class="recipe-card-kicker">Luxury Bakery Studio</div><div class="hero-message"><h2 id="heroTitle">${esc(heroMessage.title)}</h2><p id="heroSubtitle">${esc(heroMessage.text)}</p></div><div class="hint" style="color:#f2dfcf;margin:10px 0 0">${new Date().toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</div><div class="actions"><button class="btn secondary" onclick="App.openPlanner()">פתיחת תכנון השבוע</button><button class="btn ghost" onclick="App.newOrder()">הזמנה חדשה</button></div></div><div class="hero-stats"><div class="hero-stat"><strong>${todayTasks.length}</strong><span>משימות פתוחות היום</span></div><div class="hero-stat"><strong>${bags}</strong><span>שקיות בהזמנות פעילות</span></div><div class="hero-stat"><strong>${shopping().length}</strong><span>חוסרים לקנייה</span></div><div class="hero-stat"><strong>${os.length}</strong><span>הזמנות פעילות</span></div></div></section>
  <div class="grid four" style="margin-top:16px"><div class="metric"><div class="label">הזמנות פעילות</div><div class="value">${os.length}</div></div><div class="metric"><div class="label">הכנסה צפויה</div><div class="value">${money(os.reduce((s,o)=>s+revenue(o),0))}</div></div><div class="metric"><div class="label">משימות להיום</div><div class="value">${todayTasks.length}</div></div><div class="metric"><div class="label">מלאי נמוך</div><div class="value">${low}</div></div></div>
  <div class="grid two" style="margin-top:16px"><div class="card"><div class="section-head"><h2>הזמנות קרובות</h2><button class="btn small secondary" onclick="App.newOrder()">+ הזמנה</button></div>${up.length?`<div class="list">${up.map(o=>`<div class="list-item"><div class="item-row"><div><div class="title">${esc(o.customer)}</div><div class="meta">${dateText(o.dueAt)} · ${esc(o.status)} · ${money(revenue(o))}</div></div><span class="badge rose">${esc(o.delivery)}</span></div></div>`).join('')}</div>`:'<div class="empty">אין הזמנות פעילות</div>'}</div><div class="card"><div class="section-head"><h2>היום בייצור</h2><button class="btn small ghost" onclick="App.go('planner')">לכל השבוע</button></div>${ts.filter(t=>t.date===today).map(taskHtml).join('')||'<div class="empty">אין משימות להיום</div>'}</div></div>
  <div class="grid two" style="margin-top:16px"><div class="card"><h2>קניות נדרשות</h2>${shopping().slice(0,6).map(i=>`<div class="kpi-line"><span>${esc(i.name)}</span><strong>${showQty(i.need,i.unit)}</strong></div>`).join('')||'<div class="empty">אין חוסרים</div>'}</div><div class="card"><h2>פעולות מהירות</h2><div class="actions" style="margin-top:14px"><button class="btn" onclick="App.newRecipe()">מתכון חדש</button><button class="btn secondary" onclick="App.importRecipe()">✨ הדבקת מתכון</button><button class="btn ghost" onclick="App.newInventory()">עדכון מלאי</button></div></div></div>`;
  revealHeroMessage();
}

function renderOrders(){const rows=state.orders.slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));document.getElementById('view-orders').innerHTML=`<div class="card"><div class="section-head"><div><h2>הזמנות</h2><div class="hint">הכמות בכל מוצר היא מספר שקיות. כל הזמנה מזינה את תכנון הייצור והקניות.</div></div><button class="btn secondary" onclick="App.newOrder()">+ הזמנה חדשה</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>לקוחה</th><th>מועד</th><th>שקיות</th><th>סטטוס</th><th>תשלום</th><th>סכום</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.customer)}</strong><div class="muted">${esc(o.phone||'')}</div></td><td>${dateText(o.dueAt)}<div class="muted">${esc(o.delivery)}</div></td><td>${(o.items||[]).map(i=>`${esc(recipe(i.recipeId)?.name||'מתכון נמחק')} × ${fmt(i.qty,0)} שקיות`).join('<br>')}</td><td><span class="badge">${esc(o.status)}</span></td><td>${o.paid?'<span class="badge green">שולם</span>':'<span class="badge red">לא שולם</span>'}</td><td class="money">${money(revenue(o))}</td><td><div class="actions"><button class="btn small ghost" onclick="App.editOrder('${o.id}')">עריכה</button><button class="btn small danger" onclick="App.deleteOrder('${o.id}')">מחיקה</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">עדיין אין הזמנות</div>'}</div>`}
function orderRow(i){return`<div class="repeat-row order-item-row"><div class="field"><label>מתכון</label><select class="oi-r" required><option value="">בחירה</option>${state.recipes.map(r=>`<option value="${r.id}" ${i.recipeId===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="field"><label>מספר שקיות</label><input class="oi-q" type="number" min="1" step="1" value="${i.qty||1}"></div><div></div><div></div><button type="button" class="btn small danger" onclick="this.closest('.order-item-row').remove()">הסר</button></div>`}
function orderForm(o={id:'',customer:'',phone:'',dueAt:'',delivery:'איסוף עצמי',status:'חדשה',paid:false,notes:'',items:[]}){modal(o.id?'עריכת הזמנה':'הזמנה חדשה',`<form id="orderForm"><input type="hidden" name="id" value="${esc(o.id)}"><div class="form-grid"><div class="field"><label>שם הלקוחה</label><input name="customer" required value="${esc(o.customer)}"></div><div class="field"><label>טלפון</label><input name="phone" value="${esc(o.phone)}"></div><div class="field"><label>מועד אספקה</label><input name="dueAt" type="datetime-local" required value="${esc((o.dueAt||'').slice(0,16))}"></div><div class="field"><label>מסירה</label><select name="delivery">${['איסוף עצמי','משלוח'].map(x=>`<option ${o.delivery===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>סטטוס</label><select name="status">${STATUSES.map(x=>`<option ${o.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>תשלום</label><select name="paid"><option value="false" ${!o.paid?'selected':''}>לא שולם</option><option value="true" ${o.paid?'selected':''}>שולם</option></select></div><div class="field full"><label>מוצרים ומספר שקיות</label><div id="orderItems">${(o.items.length?o.items:[{recipeId:'',qty:1}]).map(orderRow).join('')}</div><button type="button" class="btn small secondary" onclick="App.addOrderItem()">+ מוצר</button></div><div class="field full"><label>הערות</label><textarea name="notes">${esc(o.notes)}</textarea></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירה</button><button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);document.getElementById('orderForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),ex=state.orders.find(x=>x.id===f.get('id')),items=[...document.querySelectorAll('.order-item-row')].map(r=>({recipeId:r.querySelector('.oi-r').value,qty:Math.max(1,Math.floor(Number(r.querySelector('.oi-q').value||0)))})).filter(x=>x.recipeId&&x.qty);if(!items.length)return alert('יש להוסיף מוצר');const x={id:f.get('id')||id('ord'),customer:f.get('customer'),phone:f.get('phone'),dueAt:f.get('dueAt'),delivery:f.get('delivery'),status:f.get('status'),paid:f.get('paid')==='true',notes:f.get('notes'),items,createdAt:ex?.createdAt||new Date().toISOString()};if(ex)Object.assign(ex,x);else state.orders.push(x);await persist();close();render()}}

function renderPlanner(){
  const tasks=generatedTasks(),base=addDays(weekStart(new Date()),plannerWeekOffset*7),days=Array.from({length:7},(_,i)=>addDays(base,i)),today=dayKey(new Date());
  const controls=`<div class="planner-toolbar"><div><h2>תכנון שבועי ויומי</h2><div class="hint">גררי משימה ליום אחר, סמני ביצוע או פתחי אותה לשינוי שעה ומשך.</div></div><div class="actions"><button class="btn small ghost" onclick="App.plannerPrev()">‹ שבוע קודם</button><button class="btn small ghost" onclick="App.plannerToday()">השבוע</button><button class="btn small ghost" onclick="App.plannerNext()">שבוע הבא ›</button><button class="btn small secondary" onclick="App.buildPlan()">✨ בנה לי שבוע עבודה</button><button class="btn small" onclick="App.newManualTask()">+ משימה ידנית</button><button class="btn small ghost" onclick="window.print()">הדפסה</button></div></div>`;
  const toggle=`<div class="inner-tabs"><button class="${plannerMode==='week'?'active':''}" onclick="App.setPlannerMode('week')">שבוע</button><button class="${plannerMode==='day'?'active':''}" onclick="App.setPlannerMode('day')">יום</button></div>`;
  let body='';
  if(plannerMode==='week'){
    body=`<div class="planner-week">${days.map(d=>{const key=dayKey(d),list=tasks.filter(t=>t.date===key),minutes=list.reduce((a,t)=>a+Number(t.duration||0),0),over=minutes>workdayCapacity();return`<section class="planner-day ${over?'overload':''} ${key===today?'today':''}" ondragover="event.preventDefault()" ondrop="App.dropPlanTask(event,'${key}')"><div class="planner-day-head"><strong>${d.toLocaleDateString('he-IL',{weekday:'short',day:'numeric',month:'numeric'})}</strong><span>${Math.round(minutes/60*10)/10} שעות${over?' ⚠':''}</span></div>${list.map(planCardHtml).join('')||'<div class="muted" style="text-align:center;padding:20px 4px">פנוי</div>'}</section>`}).join('')}</div>`;
  }else{
    const list=tasks.filter(t=>t.date===plannerDay);body=`<div class="card"><div class="section-head"><div><h2>סדר היום</h2><div class="hint">${new Date(plannerDay+'T12:00').toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</div></div><input type="date" value="${plannerDay}" onchange="App.setPlannerDay(this.value)"></div><div class="planner-day-list">${list.map(t=>`<div class="day-agenda-row"><strong>${esc(t.time)}</strong><div>${planCardHtml(t)}</div></div>`).join('')||'<div class="empty">אין משימות ביום הזה</div>'}</div></div>`;
  }
  document.getElementById('view-planner').innerHTML=`${controls}<div class="notice ${plannerSuggestions(tasks).includes('עמוסים')?'warning':'success'}">${esc(plannerSuggestions(tasks))}</div><div class="planner-legend"><span class="badge">קניות</span><span class="badge gold">תת־מתכון</span><span class="badge rose">אפייה ואריזה</span><span class="badge green">מסירה</span></div>${toggle}${body}`;
}
function planCardHtml(t){return`<article class="plan-card type-${esc(t.type)} ${t.done?'done':''}" draggable="true" ondragstart="App.dragPlanTask(event,'${esc(t.key)}')" onclick="App.editPlanTask('${esc(t.key)}')"><div class="plan-time">${esc(t.time)} · ${fmt(t.duration,0)} דק׳</div><div class="plan-title">${esc(t.text)}</div><div class="meta">${esc(t.recipe||'משימה אישית')}${t.customer?' · '+esc(t.customer):''}${t.source&&t.source!==t.recipe?' · '+esc(t.source):''}</div></article>`}
function editPlanTask(key){const task=generatedTasks().find(t=>t.key===key);if(!task)return;modal('עריכת משימה',`<form id="planTaskForm"><div class="notice"><strong>${esc(task.text)}</strong><br>${esc(task.recipe||'')} ${task.customer?'· '+esc(task.customer):''}</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>תאריך</label><input name="date" type="date" value="${esc(task.date)}"></div><div class="field"><label>שעה</label><input name="time" type="time" value="${esc(task.time)}"></div><div class="field"><label>משך בדקות</label><input name="duration" type="number" min="5" step="5" value="${task.duration||30}"></div><div class="field"><label>סטטוס</label><select name="done"><option value="false" ${!task.done?'selected':''}>פתוחה</option><option value="true" ${task.done?'selected':''}>בוצעה</option></select></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירה</button>${task.manual?`<button type="button" class="btn danger" onclick="App.deleteManualTask('${esc(task.key)}')">מחיקה</button>`:''}<button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);document.getElementById('planTaskForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);state.planOverrides[key]={date:f.get('date'),time:f.get('time'),duration:Number(f.get('duration')||30)};state.checkedTasks[key]=f.get('done')==='true';await persist();close();render()}}
function manualTaskForm(){modal('משימה ידנית חדשה',`<form id="manualTaskForm"><div class="form-grid"><div class="field full"><label>משימה</label><input name="text" required placeholder="למשל: הדפסת מדבקות"></div><div class="field"><label>תאריך</label><input name="date" type="date" required value="${plannerDay||dayKey(new Date())}"></div><div class="field"><label>שעה</label><input name="time" type="time" value="${state.settings.workStart||'08:00'}"></div><div class="field"><label>משך בדקות</label><input name="duration" type="number" min="5" step="5" value="30"></div><div class="field"><label>סוג</label><select name="type">${Object.entries(TASK_TYPES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div></div><div class="actions" style="margin-top:14px"><button class="btn">הוספה</button><button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);document.getElementById('manualTaskForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),key=id('manual');state.manualTasks.push({key,text:f.get('text'),date:f.get('date'),time:f.get('time'),duration:Number(f.get('duration')||30),type:f.get('type'),recipe:'',customer:'',batches:0,qty:0,source:'',manual:true});await persist();close();render()}}

function renderRecipes(){document.getElementById('view-recipes').innerHTML=`<div class="card"><div class="section-head"><div><h2>מתכונים</h2><div class="hint">ניהול מתכונים רגילים ומורכבים, תתי־מתכונים, משקל סופי ותפוקה בשקיות.</div></div><div class="actions"><button class="btn ghost" onclick="App.importRecipe()">✨ הדבקת מתכון</button><button class="btn secondary" onclick="App.newRecipe()">+ מתכון חדש</button></div></div>${state.recipes.length?`<div class="recipe-book-grid">${state.recipes.map(r=>{const p=packageSummary(r),c=recipeCost(r);return`<article class="recipe-card"><button class="recipe-card-main" onclick="App.editRecipe('${r.id}')"><div class="recipe-card-kicker">${r.subRecipes?.length?'מתכון מורכב':'מתכון רגיל'} · ${esc(r.category||'אחר')}</div><h3>${esc(r.name)}</h3><div class="recipe-card-meta"><span>${p.fullBags} שקיות × ${fmt(p.packageWeight,0)} גרם</span><span>יתרה ${showQty(p.remainder,'גרם')}</span><span>${money(c.perUnit)} עלות לשקית</span></div></button><div class="recipe-card-actions"><button class="btn small ghost" onclick="App.editRecipe('${r.id}')">עריכה</button><button class="btn small secondary" onclick="App.weightCalc('${r.id}')">התאמת כמות</button><button class="btn small danger" onclick="App.deleteRecipe('${r.id}')">מחיקה</button></div></article>`}).join('')}</div>`:'<div class="empty">עדיין אין מתכונים. אפשר להדביק מתכון שלם והמערכת תחלק אותו לשדות ותציג אזהרות לבדיקה.</div>'}</div>`}
function ingredientRow(i={},sub=false){return`<div class="repeat-row ingredient-row ${sub?'sub-ingredient-row':''}"><div class="field"><label>רכיב</label><input class="ri-n" value="${esc(i.name||'')}"></div><div class="field"><label>כמות</label><input class="ri-q" type="number" min="0" step=".01" value="${i.qty??''}"></div><div class="field"><label>יחידה</label><select class="ri-u">${UNITS.map(u=>`<option ${i.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>קטגוריה</label><select class="ri-c">${CATS.map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select><input class="ri-link" type="hidden" value="${esc(i.linkedSubRecipeId||'')}"></div><button type="button" class="btn small danger" onclick="App.removeIngredient(this)">הסר</button></div>`}
function stepRow(s={},sub=false){return`<div class="repeat-row step-row ${sub?'sub-step-row':''}"><div class="field"><label>תיאור הפעולה</label><input class="rs-t" value="${esc(s.text||'')}"></div><div class="field"><label>ימים לפני מסירה</label><input class="rs-d" type="number" min="0" value="${s.daysBefore||0}"></div><div class="field"><label>שעה</label><input class="rs-h" type="time" value="${esc(s.time||'')}"></div><div class="field"><label>משך בדקות</label><input class="rs-m" type="number" min="0" step="5" value="${s.durationMin||0}"></div><button type="button" class="btn small danger" onclick="this.closest('.step-row').remove()">הסר</button></div>`}
function subRecipeCard(s={id:id('sub'),name:'תת־מתכון',usedQtyGrams:0,evaporationPct:0,prepMin:30,restMin:30,bakeMin:0,ovenTemp:0,notes:'',ingredients:[],steps:[]}){return`<section class="subrecipe-card" data-sub-id="${esc(s.id)}"><div class="subrecipe-head"><input class="sub-name" value="${esc(s.name)}" aria-label="שם תת־המתכון"><button type="button" class="btn small danger" onclick="this.closest('.subrecipe-card').remove();App.updateRecipeWeightPreview()">הסרת תת־מתכון</button></div><div class="form-grid three"><div class="field"><label>כמות מתת־המתכון שנכנסת למתכון הראשי — גרם</label><input class="sub-used" type="number" min="0" step=".01" value="${s.usedQtyGrams||0}"></div><div class="field"><label>אחוז אידוי</label><input class="sub-evap" type="number" min="0" max="100" step=".1" value="${s.evaporationPct||0}"></div><div class="field"><label>זמן הכנה פעיל</label><input class="sub-prep" type="number" min="0" value="${s.prepMin||0}"></div><div class="field"><label>מנוחה/קירור</label><input class="sub-rest" type="number" min="0" value="${s.restMin||0}"></div><div class="field"><label>זמן חימום/אפייה</label><input class="sub-bake" type="number" min="0" value="${s.bakeMin||0}"></div><div class="field"><label>טמפרטורה</label><input class="sub-temp" type="number" min="0" value="${s.ovenTemp||0}"></div><div class="field full"><label>מצרכי תת־המתכון</label><div class="sub-ingredients">${(s.ingredients.length?s.ingredients:[{name:'',qty:'',unit:'גרם',category:'אחר'}]).map(i=>ingredientRow(i,true)).join('')}</div><button type="button" class="btn small secondary" onclick="App.addSubIngredient(this)">+ רכיב לתת־מתכון</button></div><div class="field full"><label>שלבי תת־המתכון</label><div class="sub-steps">${(s.steps.length?s.steps:[{text:'',daysBefore:3,time:'',durationMin:0}]).map(x=>stepRow(x,true)).join('')}</div><button type="button" class="btn small secondary" onclick="App.addSubStep(this)">+ שלב לתת־מתכון</button></div><div class="field full"><label>הערות</label><textarea class="sub-notes">${esc(s.notes||'')}</textarea></div><div class="field full"><div class="sub-weight-preview notice"></div></div></div></section>`}
function readIngredientRows(container){return[...container.querySelectorAll(':scope > .ingredient-row')].map(x=>({name:x.querySelector('.ri-n').value.trim(),qty:Number(x.querySelector('.ri-q').value||0),unit:x.querySelector('.ri-u').value,category:x.querySelector('.ri-c').value,linkedSubRecipeId:x.querySelector('.ri-link')?.value||''})).filter(x=>x.name&&x.qty)}
function readStepRows(container){return[...container.querySelectorAll(':scope > .step-row')].map(x=>({text:x.querySelector('.rs-t').value.trim(),daysBefore:Number(x.querySelector('.rs-d').value||0),time:x.querySelector('.rs-h').value,durationMin:Number(x.querySelector('.rs-m').value||0)})).filter(x=>x.text)}
function readRecipeFormIngredients(){const c=document.getElementById('recipeIngredients');return c?readIngredientRows(c):[]}
function readSubRecipes(){return[...document.querySelectorAll('.subrecipe-card')].map(card=>({id:card.dataset.subId||id('sub'),name:card.querySelector('.sub-name').value.trim()||'תת־מתכון',usedQtyGrams:Number(card.querySelector('.sub-used').value||0),evaporationPct:Number(card.querySelector('.sub-evap').value||0),prepMin:Number(card.querySelector('.sub-prep').value||0),restMin:Number(card.querySelector('.sub-rest').value||0),bakeMin:Number(card.querySelector('.sub-bake').value||0),ovenTemp:Number(card.querySelector('.sub-temp').value||0),notes:card.querySelector('.sub-notes').value,ingredients:readIngredientRows(card.querySelector('.sub-ingredients')),steps:readStepRows(card.querySelector('.sub-steps'))}))}
function updateRecipeWeightPreview(){
  const form=document.getElementById('recipeForm'),box=document.getElementById('recipeWeightPreview');if(!form||!box)return;
  const ingredients=readRecipeFormIngredients(),evaporationPct=Number(form.elements.evaporationPct?.value||0),packageWeight=Math.max(1,Number(form.elements.packageWeight?.value||200)),w=calculateIngredientListWeight(ingredients,evaporationPct),p={fullBags:Math.floor(w.finalWeight/packageWeight),remainder:w.finalWeight%packageWeight};
  if(form.elements.yieldUnits)form.elements.yieldUnits.value=p.fullBags;if(form.elements.unitWeight)form.elements.unitWeight.value=packageWeight;
  box.innerHTML=w.rawWeight?`<strong>משקל המתכון הראשי:</strong> לפני אפייה ${showQty(w.rawWeight,'גרם')} · אידוי משוער ${showQty(w.evaporationLoss,'גרם')} · משקל סופי ${showQty(w.finalWeight,'גרם')}<br><strong>תפוקת אריזה:</strong> ${p.fullBags} שקיות מלאות × ${fmt(packageWeight,0)} גרם · יתרה ${showQty(p.remainder,'גרם')}${w.estimatedCount?`<div class="hint">החישוב כולל ${w.estimatedCount} המרות ביתיות משוערות.</div>`:''}${w.excluded.length?`<div class="hint">לא נמצאה המרה עבור: ${w.excluded.map(esc).join(', ')}.</div>`:''}`:'הוסיפי רכיבים וכמויות כדי לחשב משקל ותפוקת שקיות.';
  document.querySelectorAll('.subrecipe-card').forEach(card=>{const s={ingredients:readIngredientRows(card.querySelector('.sub-ingredients')),evaporationPct:Number(card.querySelector('.sub-evap').value||0)},sw=calculateSubRecipeWeight(s),used=Number(card.querySelector('.sub-used').value||0),batches=sw.finalWeight&&used?Math.ceil(used/sw.finalWeight):used?0:1,left=sw.finalWeight*batches-used;card.querySelector('.sub-weight-preview').innerHTML=sw.rawWeight?`תפוקת תת־המתכון: <strong>${showQty(sw.finalWeight,'גרם')}</strong>. נדרש במתכון הראשי: <strong>${showQty(used,'גרם')}</strong>${used?` · אצוות נדרשות: <strong>${batches}</strong> · יתרה: <strong>${showQty(Math.max(0,left),'גרם')}</strong>`:''}${sw.excluded.length?`<div class="hint">לא חושבו: ${sw.excluded.map(esc).join(', ')}</div>`:''}`:'הוסיפי מצרכים לתת־המתכון.'})
}
function recipeForm(raw={}){
  const r=migrateRecipe({id:'',name:'',category:'עוגיות',yieldUnits:1,packageWeight:200,unitWeight:200,prepMin:30,restMin:60,bakeMin:12,ovenTemp:175,traysPerBatch:1,unitsPerTray:12,shelfLifeDays:4,packagingCost:1,wastePct:5,evaporationPct:12,salePrice:12,allergens:'',notes:'',ingredients:[],steps:[],subRecipes:[],warnings:[],...raw});
  modal(r.id?'עריכת מתכון':'מתכון חדש',`<form id="recipeForm"><input type="hidden" name="id" value="${esc(r.id)}"><div class="form-grid three"><div class="field"><label>שם המתכון</label><input name="name" required value="${esc(r.name)}"></div><div class="field"><label>קטגוריה</label><input name="category" value="${esc(r.category)}"></div><div class="field"><label>משקל יעד לשקית</label><input name="packageWeight" type="number" min="1" step="1" value="${r.packageWeight}"></div><div class="field"><label>מספר שקיות מלאות — מחושב</label><input name="yieldUnits" type="number" readonly value="${r.yieldUnits||0}"></div><div class="field"><label>משקל שקית — מחושב</label><input name="unitWeight" type="number" readonly value="${r.packageWeight}"></div><div class="field"><label>אחוז אידוי מהמים באפייה</label><input name="evaporationPct" type="number" min="0" max="100" step=".1" value="${r.evaporationPct}"><div class="hint">האחוז חל רק על המים המזוהים ברכיבים.</div></div><div class="field"><label>זמן הכנה פעיל</label><input name="prepMin" type="number" min="0" value="${r.prepMin||0}"></div><div class="field"><label>מנוחה/קירור</label><input name="restMin" type="number" min="0" value="${r.restMin||0}"></div><div class="field"><label>זמן אפייה</label><input name="bakeMin" type="number" min="0" value="${r.bakeMin||0}"></div><div class="field"><label>טמפרטורה</label><input name="ovenTemp" type="number" value="${r.ovenTemp||0}"></div><div class="field"><label>מגשים לאצווה</label><input name="traysPerBatch" type="number" min="1" value="${r.traysPerBatch||1}"></div><div class="field"><label>יחידות במגש</label><input name="unitsPerTray" type="number" min="1" value="${r.unitsPerTray||1}"></div><div class="field"><label>חיי מדף בימים</label><input name="shelfLifeDays" type="number" min="0" value="${r.shelfLifeDays||0}"></div><div class="field"><label>עלות אריזה לשקית</label><input name="packagingCost" type="number" step=".01" min="0" value="${r.packagingCost||0}"></div><div class="field"><label>אחוז בזבוז</label><input name="wastePct" type="number" min="0" value="${r.wastePct||0}"></div><div class="field"><label>מחיר מכירה לשקית</label><input name="salePrice" type="number" step=".01" min="0" value="${r.salePrice||0}"></div><div class="field"><label>אלרגנים</label><input name="allergens" value="${esc(r.allergens)}"></div>${r.warnings?.length?`<div class="field full"><div class="notice warning"><strong>נקודות לבדיקה מהייבוא:</strong><ul class="warning-list">${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></div>`:''}<div class="field full"><label>מצרכי המתכון הראשי</label><div id="recipeIngredients">${(r.ingredients.length?r.ingredients:[{name:'',qty:'',unit:'גרם',category:'יבשים'}]).map(i=>ingredientRow(i,false)).join('')}</div><button type="button" class="btn small secondary" onclick="App.addIngredient()">+ רכיב</button></div><div class="field full"><div id="recipeWeightPreview" class="notice"></div></div><div class="field full"><div class="section-head"><div><label>תתי־מתכונים והכנות מוקדמות</label><div class="hint">למשל טופי בייטס, קרם, מילוי או רוטב שצריך להכין לפני המתכון הראשי.</div></div><button type="button" class="btn small secondary" onclick="App.addSubRecipe()">+ תת־מתכון</button></div><div id="subRecipes">${(r.subRecipes||[]).map(subRecipeCard).join('')}</div></div><div class="field full"><label>שלבי המתכון הראשי</label><div id="recipeSteps">${(r.steps.length?r.steps:[{text:'',daysBefore:1,time:'',durationMin:0}]).map(s=>stepRow(s,false)).join('')}</div><button type="button" class="btn small secondary" onclick="App.addStep()">+ שלב</button></div><div class="field full"><label>הערות, טיפים ואחסון</label><textarea name="notes">${esc(r.notes)}</textarea></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירה</button><button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);
  const form=document.getElementById('recipeForm');form.addEventListener('input',updateRecipeWeightPreview);form.addEventListener('change',updateRecipeWeightPreview);updateRecipeWeightPreview();
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),ex=state.recipes.find(x=>x.id===f.get('id')),ingredients=readRecipeFormIngredients(),steps=readStepRows(document.getElementById('recipeSteps')),subRecipes=readSubRecipes(),packageWeight=Math.max(1,Number(f.get('packageWeight')||200));subRecipes.forEach(s=>{const mainIngredient=ingredients.find(i=>i.linkedSubRecipeId===s.id||cleanIngredientName(i.name)===cleanIngredientName(s.name));if(mainIngredient){mainIngredient.linkedSubRecipeId=s.id;s.usedQtyGrams=ingredientWeightData(mainIngredient).grams||s.usedQtyGrams}else if(s.usedQtyGrams>0){ingredients.push({name:s.name,qty:s.usedQtyGrams,unit:'גרם',category:'תוספות',linkedSubRecipeId:s.id})}});const weight=calculateIngredientListWeight(ingredients,Number(f.get('evaporationPct')||0)),fullBags=Math.floor(weight.finalWeight/packageWeight);const obj=migrateRecipe({id:f.get('id')||id('rec'),name:f.get('name'),category:f.get('category'),packageWeight,yieldUnits:Math.max(1,fullBags),unitWeight:packageWeight,evaporationPct:Number(f.get('evaporationPct')||0),prepMin:Number(f.get('prepMin')||0),restMin:Number(f.get('restMin')||0),bakeMin:Number(f.get('bakeMin')||0),ovenTemp:Number(f.get('ovenTemp')||0),traysPerBatch:Number(f.get('traysPerBatch')||1),unitsPerTray:Number(f.get('unitsPerTray')||1),shelfLifeDays:Number(f.get('shelfLifeDays')||0),packagingCost:Number(f.get('packagingCost')||0),wastePct:Number(f.get('wastePct')||0),salePrice:Number(f.get('salePrice')||0),allergens:f.get('allergens'),notes:f.get('notes'),ingredients,steps,subRecipes,warnings:[]});if(ex)Object.assign(ex,obj);else state.recipes.push(obj);await persist();close();render()};
}
function weightCalculator(r){if(!r)return;const base=calculateRecipeWeight(r);if(!base.finalWeight)return alert('לא ניתן לחשב משקל סופי לפני הזנת מצרכים ניתנים להמרה.');const p=packageSummary(r);modal(`התאמת ${r.name}`,`<div class="inner-tabs"><button class="active" onclick="App.scaleMode('weight',this)">לפי משקל סופי</button><button onclick="App.scaleMode('bags',this)">לפי מספר שקיות</button></div><div class="form-grid"><div class="field" id="scaleWeightField"><label>משקל סופי רצוי בק״ג</label><input id="targetWeightValue" type="number" min=".01" step=".01" value="${Math.round(base.finalWeight/10)/100}"></div><div class="field" id="scaleBagsField" hidden><label>מספר שקיות רצוי</label><input id="targetBagsValue" type="number" min="1" step="1" value="${Math.max(1,p.fullBags)}"></div><div class="field"><label>משקל לשקית</label><input id="targetPackageWeight" type="number" min="1" value="${p.packageWeight}"></div></div><div id="weightScaleSummary" class="notice" style="margin-top:12px"></div><div id="weightScaleResults" style="margin-top:12px"></div><div class="actions" style="margin-top:14px"><button class="btn secondary" id="copyWeightPlan" type="button">העתקת רשימת מצרכים</button><button class="btn ghost" type="button" onclick="App.close()">סגירה</button></div>`);window.__scaleMode='weight';const update=()=>{const mode=window.__scaleMode||'weight',pkg=Math.max(1,Number(document.getElementById('targetPackageWeight').value||r.packageWeight||200)),targetGrams=mode==='bags'?Math.max(1,Number(document.getElementById('targetBagsValue').value||1))*pkg:Math.max(0,Number(document.getElementById('targetWeightValue').value||0))*1000,factor=targetGrams/base.finalWeight,rows=expandedIngredients(r).map(i=>({...i,scaledQty:Number(i.qty||0)*factor})),bags=Math.floor(targetGrams/pkg),rem=targetGrams-bags*pkg;document.getElementById('weightScaleSummary').innerHTML=`המתכון הבסיסי נותן <strong>${showQty(base.finalWeight,'גרם')}</strong>. יעד: <strong>${showQty(targetGrams,'גרם')}</strong> · מקדם <strong>${fmt(factor,3)}</strong> · ${bags} שקיות מלאות · יתרה ${showQty(rem,'גרם')}.`;document.getElementById('weightScaleResults').innerHTML=`<div class="table-wrap"><table><thead><tr><th>רכיב</th><th>כמות חדשה</th><th>מקור</th></tr></thead><tbody>${rows.map(i=>`<tr><td>${esc(i.name)}</td><td><strong>${fmt(i.scaledQty,2)} ${esc(i.unit)}</strong></td><td>${esc(i.sourceSubRecipe||'מתכון ראשי')}</td></tr>`).join('')}</tbody></table></div>`;window.__scaleCopy=`${r.name}\nמשקל סופי רצוי: ${showQty(targetGrams,'גרם')}\n${bags} שקיות × ${pkg} גרם\nמקדם: ${fmt(factor,3)}\n\n`+rows.map(i=>`${i.name}: ${fmt(i.scaledQty,2)} ${i.unit}${i.sourceSubRecipe?' ('+i.sourceSubRecipe+')':''}`).join('\n')};['targetWeightValue','targetBagsValue','targetPackageWeight'].forEach(x=>document.getElementById(x).addEventListener('input',update));document.getElementById('copyWeightPlan').onclick=async()=>{try{await navigator.clipboard.writeText(window.__scaleCopy);document.getElementById('copyWeightPlan').textContent='✓ הועתק'}catch(e){alert(window.__scaleCopy)}};window.__updateScale=update;update()}

function importRecipeModal(){modal('הדבקת מתכון חכמה',`<div class="field"><label>הדביקי את המתכון המלא</label><textarea id="recipeImportText" class="recipe-import-text" placeholder="שם המתכון\n\nתת־מתכון: טופי בייטס\n115 גרם חמאה...\n\nלעוגיות\n220 גרם קמח...\n\nאופן הכנה:\n..."></textarea><div class="hint">המערכת מפרידה בין מצרכים, פעולות, טיפים ותתי־מתכונים. היא מציגה סתירות וחוסרים לבדיקה ולא שומרת אוטומטית.</div></div><div id="recipeImportStatus"></div><div class="actions" style="margin-top:14px"><button class="btn secondary" type="button" onclick="App.analyzeRecipeImport()">ניתוח והצגת מסך בדיקה</button><button class="btn ghost" type="button" onclick="App.close()">ביטול</button></div>`);setTimeout(()=>document.getElementById('recipeImportText')?.focus(),50)}
async function analyzeRecipeImport(){const text=document.getElementById('recipeImportText')?.value.trim(),status=document.getElementById('recipeImportStatus');if(!text)return alert('יש להדביק מתכון');if(status)status.innerHTML='<div class="notice" style="margin-top:12px">מנתחת מצרכים, שלבים ותתי־מתכונים…</div>';const ai=await parseRecipeWithAI(text);pendingImport=sanitizeImportedRecipe(ai||localParseRecipe(text),text);reviewImportedRecipe(pendingImport)}
function reviewImportedRecipe(r){const allSections=[...r.subRecipes,{name:'המתכון הראשי',ingredients:r.ingredients,steps:r.steps}];modal('בדיקת המתכון לפני שמירה',`${r.warnings?.length?`<div class="notice warning"><strong>נדרשת בדיקה:</strong><ul class="warning-list">${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:'<div class="notice success">לא נמצאו סתירות בולטות. עדיין מומלץ לעבור על הכמויות.</div>'}<div class="import-summary"><div><strong>${allSections.length}</strong><div class="muted">חלקי מתכון</div></div><div><strong>${r.ingredients.length+r.subRecipes.reduce((a,s)=>a+s.ingredients.length,0)}</strong><div class="muted">מצרכים</div></div><div><strong>${r.steps.length+r.subRecipes.reduce((a,s)=>a+s.steps.length,0)}</strong><div class="muted">פעולות</div></div><div><strong>${r.subRecipes.length}</strong><div class="muted">תתי־מתכונים</div></div></div>${allSections.map(s=>`<div class="review-section"><strong>${esc(s.name)}</strong><div class="meta">${s.ingredients.length} מצרכים · ${s.steps.length} שלבים</div><div class="muted" style="margin-top:8px">${s.ingredients.slice(0,5).map(i=>`${fmt(i.qty)} ${esc(i.unit)} ${esc(i.name)}`).join(' · ')}</div></div>`).join('')}<div class="actions"><button class="btn secondary" onclick="App.openPendingRecipe()">פתיחה לעריכה ושמירה</button><button class="btn ghost" onclick="App.close()">ביטול</button></div>`)}

function recipeBookCard(r){const p=packageSummary(r);return`<article class="recipe-card" data-search="${esc((r.name+' '+r.category).toLowerCase())}" data-category="${esc(r.category||'אחר')}"><button class="recipe-card-main" onclick="App.openBookRecipe('${r.id}')"><div class="recipe-card-kicker">${esc(r.category||'מתכון')} ${r.subRecipes?.length?'· מורכב':''}</div><h3>${esc(r.name)}</h3><div class="recipe-card-meta"><span>◷ ${fmt(Number(r.prepMin||0)+Number(r.bakeMin||0),0)} דק׳</span><span>◌ ${p.fullBags} שקיות</span><span>⚖ ${showQty(p.finalWeight,'גרם')}</span></div></button><div class="recipe-card-actions"><button class="btn small secondary" onclick="App.openBookRecipe('${r.id}')">פתיחת מתכון</button><button class="btn small ghost" onclick="App.weightCalc('${r.id}')">התאמת כמות</button></div></article>`}
function renderRecipeBook(){const cats=[...new Set(state.recipes.map(r=>r.category||'אחר'))].sort((a,b)=>a.localeCompare(b,'he'));document.getElementById('view-recipebook').innerHTML=`<div class="card recipe-book-shell"><div class="section-head"><div><h2>ספר המתכונים</h2><div class="hint">תצוגה נקייה לעבודה במטבח, כולל תתי־מתכונים וסדר הכנה.</div></div><button class="btn secondary" onclick="App.importRecipe()">✨ הדבקת מתכון</button></div><div class="recipe-book-toolbar"><div class="field"><label>חיפוש</label><input id="recipeBookSearch" type="search" placeholder="שם מתכון או קטגוריה" oninput="App.filterRecipeBook()"></div><div class="field"><label>קטגוריה</label><select id="recipeBookCategory" onchange="App.filterRecipeBook()"><option value="">הכול</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div></div><div id="recipeBookGrid" class="recipe-book-grid">${state.recipes.map(recipeBookCard).join('')||'<div class="empty">עדיין אין מתכונים בספר.</div>'}</div></div>`}
function filterRecipeBook(){const q=String(document.getElementById('recipeBookSearch')?.value||'').toLowerCase().trim(),cat=document.getElementById('recipeBookCategory')?.value||'';document.querySelectorAll('#recipeBookGrid .recipe-card').forEach(card=>{card.hidden=!((!q||card.dataset.search.includes(q))&&(!cat||card.dataset.category===cat))})}
function sectionHtml(title,ingredients,steps,notes=''){return`<div class="recipe-detail-grid"><div class="card"><h3>${esc(title)} — מצרכים</h3><ul class="ingredient-list">${(ingredients||[]).map(i=>`<li><strong>${fmt(i.qty)} ${esc(i.unit)}</strong> ${esc(i.name)}</li>`).join('')||'<li>אין מצרכים</li>'}</ul></div><div class="card"><h3>אופן הכנה</h3><ol class="steps-list">${(steps||[]).map(s=>`<li>${esc(s.text)}</li>`).join('')||'<li>לא הוזנו שלבים</li>'}</ol>${notes?`<div class="notice" style="margin-top:12px">${esc(notes).replace(/\n/g,'<br>')}</div>`:''}</div></div>`}
function openBookRecipe(recipeId){const r=recipe(recipeId);if(!r)return;const p=packageSummary(r),tabs=[{id:'full',label:'מתכון מלא'},{id:'main',label:'מתכון ראשי'},...(r.subRecipes||[]).map((s,i)=>({id:`sub${i}`,label:s.name}))];const full=`${(r.subRecipes||[]).map(s=>`<div class="day-title">קודם: ${esc(s.name)}</div>${sectionHtml(s.name,s.ingredients,s.steps,s.notes)}`).join('')}<div class="day-title">אחר כך: ${esc(r.name)}</div>${sectionHtml(r.name,r.ingredients,r.steps,r.notes)}`;modal(r.name,`<div class="recipe-detail-hero"><div class="recipe-card-kicker">${esc(r.category||'מתכון')} ${r.subRecipes?.length?'· מתכון מורכב':''}</div><h3>${esc(r.name)}</h3><div class="recipe-card-meta" style="color:#f0dfd0;margin-top:12px"><span>${p.fullBags} שקיות × ${fmt(p.packageWeight,0)} גרם</span><span>משקל סופי ${showQty(p.finalWeight,'גרם')}</span><span>יתרה ${showQty(p.remainder,'גרם')}</span><span>${fmt(r.ovenTemp,0)}° · ${fmt(r.bakeMin,0)} דק׳</span></div></div><div class="inner-tabs">${tabs.map((t,i)=>`<button class="${i===0?'active':''}" onclick="App.switchBookPane('${t.id}',this)">${esc(t.label)}</button>`).join('')}</div><div id="book-full" class="book-pane active">${full}</div><div id="book-main" class="book-pane">${sectionHtml(r.name,r.ingredients,r.steps,r.notes)}</div>${(r.subRecipes||[]).map((s,i)=>`<div id="book-sub${i}" class="book-pane">${sectionHtml(s.name,s.ingredients,s.steps,s.notes)}<div class="notice" style="margin-top:12px">נדרש במתכון הראשי: <strong>${showQty(s.usedQtyGrams||0,'גרם')}</strong> · תפוקת תת־המתכון: <strong>${showQty(calculateSubRecipeWeight(s).finalWeight,'גרם')}</strong></div></div>`).join('')}<div class="actions" style="margin-top:16px"><button class="btn secondary" onclick="App.weightCalc('${r.id}')">התאמה למשקל או לשקיות</button><button class="btn ghost" onclick="App.copyRecipe('${r.id}')">העתקה</button><button class="btn ghost" onclick="window.print()">הדפסה</button></div>`)}
function recipePlainText(r){const p=packageSummary(r);return`${r.name}\n${r.category||''}\n\nתפוקה: ${p.fullBags} שקיות × ${p.packageWeight} גרם\nמשקל סופי משוער: ${showQty(p.finalWeight,'גרם')}\nיתרה: ${showQty(p.remainder,'גרם')}\n\n${(r.subRecipes||[]).map(s=>`${s.name}\nמצרכים:\n${s.ingredients.map(i=>`• ${fmt(i.qty)} ${i.unit} ${i.name}`).join('\n')}\nשלבים:\n${s.steps.map((x,i)=>`${i+1}. ${x.text}`).join('\n')}`).join('\n\n')}\n\nהמתכון הראשי\nמצרכים:\n${(r.ingredients||[]).map(i=>`• ${fmt(i.qty)} ${i.unit} ${i.name}`).join('\n')}\n\nאופן הכנה:\n${(r.steps||[]).map((s,i)=>`${i+1}. ${s.text}`).join('\n')}\n\n${r.notes||''}`}

function renderProduction(){const ts=generatedTasks(),g={},d=demand().byRecipe;ts.forEach(t=>(g[t.date]||(g[t.date]=[])).push(t));document.getElementById('view-production').innerHTML=`<div class="grid two"><div class="card"><h2>שקיות ואצוות</h2>${Object.entries(d).map(([rid,q])=>{const r=recipe(rid),yieldBags=recipeYieldBags(r),b=Math.ceil(q/yieldBags),left=b*yieldBags-q;return`<div class="kpi-line"><span>${esc(r?.name||'מתכון')}</span><strong>${fmt(q,0)} שקיות · ${b} אצוות · עודף ${fmt(left,0)} שקיות</strong></div>`}).join('')||'<div class="empty">אין ייצור מתוכנן</div>'}</div><div class="card"><h2>עומס תנור ומגשים</h2>${Object.entries(d).map(([rid,q])=>{const r=recipe(rid);if(!r)return'';const b=Math.ceil(q/recipeYieldBags(r));return`<div class="kpi-line"><span>${esc(r.name)}</span><strong>${b*(r.traysPerBatch||1)} מגשים · ${b*(r.bakeMin||0)} דק׳ תנור</strong></div>`}).join('')||'<div class="empty">אין עומס מחושב</div>'}</div></div><div class="card" style="margin-top:14px"><div class="section-head"><h2>סדר עבודה לפי יום</h2><button class="btn small ghost" onclick="App.go('planner')">פתיחת Planner</button></div>${Object.keys(g).length?Object.keys(g).sort().map(day=>`<div><div class="day-title">${new Date(day+'T12:00').toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</div>${g[day].map(taskHtml).join('')}</div>`).join(''):'<div class="empty">הוסיפי הזמנות כדי ליצור תוכנית</div>'}</div>`}
function renderShopping(){const items=shopping(),g={},opts=supplierOptions(),best=opts[0];items.forEach(i=>(g[i.category]||(g[i.category]=[])).push(i));document.getElementById('view-shopping').innerHTML=`<div class="grid two"><div class="card"><div class="section-head"><h2>רשימת קניות מאוחדת</h2><button class="btn small ghost" onclick="window.print()">הדפסה</button></div>${items.length?Object.entries(g).map(([cat,a])=>`<h3>${esc(cat)}</h3>${a.map(i=>`<div class="task ${i.checked?'done':''}"><input type="checkbox" ${i.checked?'checked':''} onchange="App.toggleShopping('${esc(i.key)}')"><div class="task-text"><strong>${esc(i.name)}</strong><div class="meta">דרוש ${showQty(i.required,i.unit)} · במלאי ${showQty(i.available,i.unit)} · לקנייה ${showQty(i.need,i.unit)}</div></div></div>`).join('')}`).join(''):'<div class="empty">אין חוסרים</div>'}</div><div class="card"><h2>המלצת סל</h2>${best?`<div class="notice"><strong>${esc(best.supplier.name)}</strong><br>פריטים ${money(best.itemsCost)} · משלוח ${money(best.delivery)} · נסיעה ${money(best.distanceCost)}<br><strong>סה"כ ${money(best.total)}</strong></div><div class="hint" style="margin-top:10px">מבוסס על המחירים שהוזנו או יובאו ועל המרחקים שהגדרת.</div>`:'<div class="empty">הוסיפי ספקים ומחירים</div>'}${opts.length?`<div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>ספק</th><th>כיסוי</th><th>סה"כ</th></tr></thead><tbody>${opts.map(o=>`<tr><td>${esc(o.supplier.name)}</td><td>${o.covered}/${items.length}</td><td class="money">${money(o.total)}</td></tr>`).join('')}</tbody></table></div>`:''}</div></div>`}

function renderInventory(){const soon=addDays(new Date(),7);document.getElementById('view-inventory').innerHTML=`<div class="card"><div class="section-head"><div><h2>מלאי</h2><div class="hint">מספר אריזות × כמות בכל אריזה = סך הכול במלאי.</div></div><button class="btn secondary" onclick="App.newInventory()">+ פריט מלאי</button></div>${state.inventory.length?`<div class="table-wrap"><table><thead><tr><th>רכיב</th><th>כמות יחידות</th><th>בכל יחידה</th><th>סה״כ במלאי</th><th>מינימום</th><th>תפוגה</th><th>מיקום</th><th>עלות לאריזה</th><th></th></tr></thead><tbody>${state.inventory.map(i=>{const count=inventoryPackageCount(i),per=inventoryAmountPerPackage(i),total=inventoryTotal(i),low=total<=inventoryMinTotal(i),exp=i.expiry&&new Date(i.expiry)<=soon;return`<tr><td><strong>${esc(i.name)}</strong>${low?'<div><span class="badge red">מלאי נמוך</span></div>':''}</td><td>${fmt(count,0)}</td><td>${showQty(per,i.unit)}</td><td><strong>${showQty(total,i.unit)}</strong></td><td>${fmt(inventoryMinPackageCount(i),0)} יחידות</td><td>${i.expiry?dateText(i.expiry):'—'} ${exp?'<span class="badge gold">קרוב</span>':''}</td><td>${esc(i.location||'')}</td><td>${money(inventoryPackCost(i))}</td><td><div class="actions"><button class="btn small ghost" onclick="App.editInventory('${i.id}')">עריכה</button><button class="btn small danger" onclick="App.deleteInventory('${i.id}')">מחיקה</button></div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">אין פריטי מלאי</div>'}</div>`}
function inventoryForm(i={id:'',name:'',packageCount:0,amountPerPackage:0,unit:'גרם',minPackageCount:0,expiry:'',location:'',costPerPackage:0,supplierId:''}){const legacy=i.packageCount===undefined,packageCount=legacy?(Number(i.qty||0)>0?1:0):inventoryPackageCount(i),amountPerPackage=legacy?Number(i.qty||0):inventoryAmountPerPackage(i),minPackageCount=legacy?(amountPerPackage>0?Math.ceil(Number(i.minQty||0)/amountPerPackage):0):inventoryMinPackageCount(i);modal(i.id?'עריכת מלאי':'פריט מלאי חדש',`<form id="invForm"><input type="hidden" name="id" value="${esc(i.id)}"><div class="form-grid"><div class="field"><label>רכיב</label><input name="name" required value="${esc(i.name)}"></div><div class="field"><label>כמות יחידות</label><input name="packageCount" type="number" step="1" min="0" value="${packageCount}"></div><div class="field"><label>כמות בכל יחידה</label><input name="amountPerPackage" type="number" step=".01" min="0" value="${amountPerPackage}"></div><div class="field"><label>יחידת מידה</label><select name="unit">${UNITS.map(u=>`<option ${i.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>מינימום יחידות</label><input name="minPackageCount" type="number" step="1" min="0" value="${minPackageCount}"></div><div class="field"><label>עלות לאריזה</label><input name="costPerPackage" type="number" step=".01" min="0" value="${inventoryPackCost(i)}"></div><div class="field"><label>תפוגה</label><input name="expiry" type="date" value="${esc(i.expiry)}"></div><div class="field"><label>מיקום אחסון</label><input name="location" value="${esc(i.location)}"></div><div class="field"><label>ספק</label><select name="supplierId"><option value="">ללא</option>${state.suppliers.map(s=>`<option value="${s.id}" ${i.supplierId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field full"><div id="inventoryTotalPreview" class="notice"></div></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירה</button><button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);const form=document.getElementById('invForm'),update=()=>{const count=Math.max(0,Math.floor(Number(form.elements.packageCount.value)||0)),per=Math.max(0,Number(form.elements.amountPerPackage.value)||0),unit=form.elements.unit.value;form.elements.packageCount.value=count;document.getElementById('inventoryTotalPreview').innerHTML=`סה״כ במלאי: <strong>${showQty(count*per,unit)}</strong> (${fmt(count,0)} × ${showQty(per,unit)})`};form.addEventListener('input',update);form.addEventListener('change',update);update();form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),ex=state.inventory.find(x=>x.id===f.get('id')),obj={id:f.get('id')||id('inv'),name:f.get('name'),packageCount:Math.max(0,Math.floor(Number(f.get('packageCount')||0))),amountPerPackage:Number(f.get('amountPerPackage')||0),unit:f.get('unit'),minPackageCount:Math.max(0,Math.floor(Number(f.get('minPackageCount')||0))),expiry:f.get('expiry'),location:f.get('location'),costPerPackage:Number(f.get('costPerPackage')||0),supplierId:f.get('supplierId')};if(ex)Object.assign(ex,obj);else state.inventory.push(obj);await persist();close();render()}}

/* ייבוא שקיפות מחירים רמי לוי */
async function readMaybeGzip(file){const buf=await file.arrayBuffer();if(file.name.toLowerCase().endsWith('.gz')){if('DecompressionStream'in window){const stream=new Blob([buf]).stream().pipeThrough(new DecompressionStream('gzip'));return await new Response(stream).text()}if(window.pako?.ungzip)return window.pako.ungzip(new Uint8Array(buf),{to:'string'});throw new Error('הדפדפן אינו תומך בפתיחת GZ. אפשר לחלץ את הקובץ ולהעלות XML.')}return new TextDecoder('utf-8').decode(buf)}
function xmlText(node,tag){return node.querySelector(tag)?.textContent?.trim()||''}
function mapPriceUnit(unitQty,quantity){const u=cleanIngredientName(unitQty);let unit='יחידה',qty=Number(quantity||1);if(/קילוגרם|קג/.test(u))unit='ק"ג';else if(/גרם/.test(u))unit='גרם';else if(/ליטר/.test(u)&&!/מילי/.test(u))unit='ליטר';else if(/מיליליטר|מל/.test(u))unit='מ"ל';else if(/יחידה/.test(u))unit='יחידה';return{unit,qty:qty||1}}
function parseRamiXML(text,fileName=''){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw new Error('קובץ XML לא תקין');const storeId=xmlText(doc,'StoreID'),chainId=xmlText(doc,'ChainID'),subChainId=xmlText(doc,'SubChainID'),items=[...doc.querySelectorAll('Items > Item')].map(node=>{const pack=mapPriceUnit(xmlText(node,'UnitQty'),xmlText(node,'Quantity'));const price=Number(xmlText(node,'ItemPrice')||0),sale=Number(xmlText(node,'DiscountedPrice')||xmlText(node,'PromoPrice')||xmlText(node,'ItemPriceWithDiscount')||0);return{barcode:xmlText(node,'ItemCode'),name:xmlText(node,'ItemName')||xmlText(node,'ManufactureItemDescription'),manufacturer:xmlText(node,'ManufactureName'),packQty:pack.qty,unit:pack.unit,price,salePrice:sale&&sale<price?sale:null,updatedAt:xmlText(node,'PriceUpdateTime')||xmlText(node,'LastSaleDateTime')}}).filter(i=>i.name&&i.price);const branch=storeId==='055'?{name:'רמת החייל',address:'דבורה הנביאה 127'}:{name:`סניף ${storeId}`,address:''};return{id:id('price'),source:'רמי לוי',fileName,chainId,subChainId,storeId,branchName:branch.name,address:branch.address,importedAt:new Date().toISOString(),items}}
async function importRamiFile(file){try{setStatus('פותחת קובץ מחירים…');const text=await readMaybeGzip(file),data=parseRamiXML(text,file.name);state.priceImports=state.priceImports.filter(x=>!(x.source==='רמי לוי'&&x.storeId===data.storeId));state.priceImports.unshift(data);await persist();alert(`יובאו ${data.items.length} מוצרים מסניף ${data.storeId} — ${data.branchName}.`);go('suppliers')}catch(e){console.error(e);alert(`לא ניתן לייבא את הקובץ: ${e.message}`)}}
function currentPriceImport(){return state.priceImports[0]||null}
function renderPriceCatalog(){const imp=currentPriceImport();if(!imp)return'<div class="empty">עדיין לא יובא קובץ מחירים.</div>';return`<div class="import-summary"><div><strong>${esc(imp.storeId)}</strong><div class="muted">מספר סניף</div></div><div><strong>${esc(imp.branchName)}</strong><div class="muted">${esc(imp.address)}</div></div><div><strong>${imp.items.length}</strong><div class="muted">מוצרים בקובץ</div></div><div><strong>${dateText(imp.importedAt)}</strong><div class="muted">מועד ייבוא</div></div></div><div class="catalog-search"><div class="field"><label>חיפוש מוצר או ברקוד</label><input id="priceCatalogSearch" placeholder="קמח, חמאה, סוכר…" oninput="App.filterPriceCatalog()"></div><div class="field"><label>תצוגה</label><select id="priceCatalogLimit" onchange="App.filterPriceCatalog()"><option value="40">40 תוצאות</option><option value="100">100 תוצאות</option><option value="500">הכול</option></select></div></div><div id="priceCatalogRows"></div>`}
function filterPriceCatalog(){const imp=currentPriceImport(),box=document.getElementById('priceCatalogRows');if(!imp||!box)return;const q=cleanIngredientName(document.getElementById('priceCatalogSearch')?.value||''),limit=Number(document.getElementById('priceCatalogLimit')?.value||40),rows=imp.items.filter(i=>!q||cleanIngredientName(i.name+' '+i.barcode+' '+i.manufacturer).includes(q)).slice(0,limit);box.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>מוצר</th><th>ברקוד</th><th>אריזה</th><th>מחיר</th><th></th></tr></thead><tbody>${rows.map((i,index)=>`<tr><td><strong>${esc(i.name)}</strong><div class="muted">${esc(i.manufacturer||'')}</div></td><td dir="ltr">${esc(i.barcode)}</td><td>${showQty(i.packQty,i.unit)}</td><td class="money">${money(i.salePrice||i.price)}${i.salePrice?`<div class="muted"><s>${money(i.price)}</s></div>`:''}</td><td><button class="btn small secondary" onclick="App.linkCatalogProduct('${esc(i.barcode)}')">קישור לרכיב</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">לא נמצאו מוצרים</div>'}
function linkCatalogProduct(barcode){const imp=currentPriceImport(),item=imp?.items.find(i=>i.barcode===barcode);if(!item)return;const suggestions=[...new Set(state.recipes.flatMap(r=>expandedIngredients(r).map(i=>i.name)))].sort((a,b)=>a.localeCompare(b,'he'));modal('קישור מוצר למחיר ספק',`<form id="linkProductForm"><div class="notice"><strong>${esc(item.name)}</strong><br>${showQty(item.packQty,item.unit)} · ${money(item.salePrice||item.price)} · ברקוד ${esc(item.barcode)}</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>שם הרכיב במתכונים</label><input name="ingredient" list="ingredientNames" required value="${esc(suggestions.find(x=>cleanIngredientName(item.name).includes(cleanIngredientName(x)))||'')}"><datalist id="ingredientNames">${suggestions.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field"><label>כמות בחבילה</label><input name="packQty" type="number" step=".01" value="${item.packQty}"></div><div class="field"><label>יחידה</label><select name="unit">${UNITS.map(u=>`<option ${u===item.unit?'selected':''}>${u}</option>`).join('')}</select></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירה במחירי רמי לוי</button><button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);document.getElementById('linkProductForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);let supplier=state.suppliers.find(s=>s.source==='rami-levy'&&s.storeId===imp.storeId);if(!supplier){supplier={id:id('sup'),name:`רמי לוי — ${imp.branchName}`,address:imp.address,distanceKm:0,deliveryCost:0,notes:`מחירים שיובאו מקובץ שקיפות מחירים, סניף ${imp.storeId}.`,source:'rami-levy',storeId:imp.storeId,prices:[]};state.suppliers.push(supplier)}const ingredient=f.get('ingredient'),existing=supplier.prices.find(p=>cleanIngredientName(p.ingredient)===cleanIngredientName(ingredient));const price={ingredient,packQty:Number(f.get('packQty')||item.packQty),unit:f.get('unit'),packPrice:Number(item.salePrice||item.price),barcode:item.barcode,productName:item.name,updatedAt:item.updatedAt||imp.importedAt};if(existing)Object.assign(existing,price);else supplier.prices.push(price);await persist();close();render()}}

function renderSuppliers(){const opts=supplierOptions(),imp=currentPriceImport();document.getElementById('view-suppliers').innerHTML=`<div class="grid two"><div class="card"><div class="section-head"><div><h2>ספקים וחנויות</h2><div class="hint">מחיר, מרחק ומשלוח לחישוב עלות אמיתית.</div></div><button class="btn secondary" onclick="App.newSupplier()">+ ספק</button></div>${state.suppliers.length?`<div class="list">${state.suppliers.map(s=>`<div class="list-item"><div class="item-row"><div><div class="title">${esc(s.name)}</div><div class="meta">${fmt(s.distanceKm)} ק"מ · משלוח ${money(s.deliveryCost)} · ${(s.prices||[]).length} מחירים</div></div><div class="actions"><button class="btn small ghost" onclick="App.editSupplier('${s.id}')">עריכה</button><button class="btn small danger" onclick="App.deleteSupplier('${s.id}')">מחיקה</button></div></div></div>`).join('')}</div>`:'<div class="empty">אין ספקים</div>'}</div><div class="card"><h2>השוואת סל נוכחי</h2>${opts.length?`<div class="table-wrap"><table><thead><tr><th>ספק</th><th>כיסוי</th><th>פריטים</th><th>משלוח</th><th>נסיעה</th><th>סה"כ</th></tr></thead><tbody>${opts.map(o=>`<tr><td>${esc(o.supplier.name)}</td><td>${o.covered}</td><td>${money(o.itemsCost)}</td><td>${money(o.delivery)}</td><td>${money(o.distanceCost)}</td><td class="money">${money(o.total)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">אין מספיק נתונים</div>'}</div></div><div class="card" style="margin-top:16px"><div class="section-head"><div><h2>ייבוא מחירי רמי לוי</h2><div class="hint">מעלה קובץ Price מסוג GZ או XML ממערכת שקיפות המחירים.</div></div><div class="actions"><button class="btn secondary" onclick="document.getElementById('ramiImportFile').click()">ייבוא קובץ</button>${imp?`<button class="btn small danger" onclick="App.deletePriceImport('${imp.id}')">מחיקת הייבוא</button>`:''}</div></div>${renderPriceCatalog()}</div>`;setTimeout(filterPriceCatalog,0)}
function priceRow(p={}){return`<div class="repeat-row price-row"><div class="field"><label>רכיב</label><input class="sp-i" value="${esc(p.ingredient||'')}"></div><div class="field"><label>כמות בחבילה</label><input class="sp-q" type="number" min="0" step=".01" value="${p.packQty||0}"></div><div class="field"><label>יחידה</label><select class="sp-u">${UNITS.map(u=>`<option ${p.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>מחיר חבילה</label><input class="sp-p" type="number" min="0" step=".01" value="${p.packPrice||0}"></div><button type="button" class="btn small danger" onclick="this.closest('.price-row').remove()">הסר</button></div>`}
function supplierForm(s={id:'',name:'',address:'',distanceKm:0,deliveryCost:0,notes:'',prices:[]}){modal(s.id?'עריכת ספק':'ספק חדש',`<form id="supForm"><input type="hidden" name="id" value="${esc(s.id)}"><div class="form-grid"><div class="field"><label>שם ספק/חנות</label><input name="name" required value="${esc(s.name)}"></div><div class="field"><label>כתובת</label><input name="address" value="${esc(s.address)}"></div><div class="field"><label>מרחק בק"מ</label><input name="distanceKm" type="number" step=".1" min="0" value="${s.distanceKm}"></div><div class="field"><label>עלות משלוח</label><input name="deliveryCost" type="number" step=".01" min="0" value="${s.deliveryCost}"></div><div class="field full"><label>מחירי אריזות</label><div id="supplierPrices">${(s.prices.length?s.prices:[{ingredient:'',packQty:1,unit:'ק"ג',packPrice:0}]).map(priceRow).join('')}</div><button type="button" class="btn small secondary" onclick="App.addPrice()">+ מחיר</button></div><div class="field full"><label>הערות</label><textarea name="notes">${esc(s.notes)}</textarea></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירה</button><button type="button" class="btn ghost" onclick="App.close()">ביטול</button></div></form>`);document.getElementById('supForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),ex=state.suppliers.find(x=>x.id===f.get('id')),prices=[...document.querySelectorAll('.price-row')].map(r=>({ingredient:r.querySelector('.sp-i').value.trim(),packQty:Number(r.querySelector('.sp-q').value||0),unit:r.querySelector('.sp-u').value,packPrice:Number(r.querySelector('.sp-p').value||0),updatedAt:new Date().toISOString()})).filter(x=>x.ingredient&&x.packQty),obj={id:f.get('id')||id('sup'),name:f.get('name'),address:f.get('address'),distanceKm:Number(f.get('distanceKm')||0),deliveryCost:Number(f.get('deliveryCost')||0),notes:f.get('notes'),prices};if(ex)Object.assign(ex,obj);else state.suppliers.push(obj);await persist();close();render()}}

function renderReports(){const os=state.orders.filter(o=>o.status!=='בוטלה'),rev=os.reduce((s,o)=>s+revenue(o),0);let cost=0,by={};os.forEach(o=>(o.items||[]).forEach(i=>{const r=recipe(i.recipeId);if(r)cost+=recipeCost(r).perUnit*Number(i.qty);by[i.recipeId]=(by[i.recipeId]||0)+Number(i.qty)}));const profit=rev-cost;document.getElementById('view-reports').innerHTML=`<div class="grid four"><div class="metric"><div class="label">הכנסות</div><div class="value">${money(rev)}</div></div><div class="metric"><div class="label">עלות משוערת</div><div class="value">${money(cost)}</div></div><div class="metric"><div class="label">רווח גולמי</div><div class="value">${money(profit)}</div></div><div class="metric"><div class="label">שיעור רווח</div><div class="value">${rev?fmt(profit/rev*100,1):0}%</div></div></div><div class="grid two" style="margin-top:14px"><div class="card"><h2>מוצרים נמכרים</h2>${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([rid,q])=>`<div class="kpi-line"><span>${esc(recipe(rid)?.name||'מתכון')}</span><strong>${fmt(q,0)} שקיות</strong></div>`).join('')||'<div class="empty">אין נתונים</div>'}</div><div class="card"><h2>רווחיות מתכונים</h2>${state.recipes.map(r=>{const c=recipeCost(r);return`<div class="kpi-line"><span>${esc(r.name)}</span><strong>${money(Number(r.salePrice)-c.perUnit)} לשקית</strong></div>`}).join('')||'<div class="empty">אין מתכונים</div>'}</div></div><div class="card" style="margin-top:14px"><div class="notice">זהו אומדן ניהולי. שכירות, מסים, עמלות, פחת והוצאות קבועות אינן נכללות אלא אם הוזנו.</div></div>`}
function renderSettings(){const c=getCloud()||{};document.getElementById('view-settings').innerHTML=`<div class="grid two"><div class="card"><h2>הגדרות העסק</h2><form id="settingsForm"><div class="form-grid"><div class="field"><label>שם העסק</label><input name="businessName" value="${esc(state.settings.businessName||'Bakery Workspace')}"></div><div class="field"><label>מטבע</label><input name="currency" value="${esc(state.settings.currency||'₪')}"></div><div class="field"><label>שכר עבודה לשעה</label><input name="laborRate" type="number" min="0" step=".01" value="${Number(state.settings.laborRate||0)}"></div><div class="field"><label>עלות נסיעה לק״מ</label><input name="distanceCostPerKm" type="number" min="0" step=".01" value="${Number(state.settings.distanceCostPerKm||0)}"></div><div class="field"><label>מספר תנורים</label><input name="ovens" type="number" min="1" step="1" value="${Number(state.settings.ovens||1)}"></div><div class="field"><label>מגשים בכל תנור</label><input name="ovenTrays" type="number" min="1" step="1" value="${Number(state.settings.ovenTrays||1)}"></div><div class="field"><label>תחילת יום עבודה</label><input name="workStart" type="time" value="${esc(state.settings.workStart||'08:00')}"></div><div class="field"><label>סיום יום עבודה</label><input name="workEnd" type="time" value="${esc(state.settings.workEnd||'18:00')}"></div></div><div class="actions" style="margin-top:14px"><button class="btn">שמירת הגדרות</button></div></form></div><div class="card"><h2>שמירה בענן</h2>${cloud.user?`<div class="notice success"><strong>מחוברת:</strong> ${esc(cloud.user.email||'')}<br><span class="muted">החיבור נשמר אוטומטית במכשיר הזה, ובכניסה הבאה המערכת תתחבר ותטען את הנתונים מהענן.</span></div><div class="actions" style="margin-top:12px"><button class="btn secondary" onclick="App.pullCloud()">רענון מהענן</button><button class="btn ghost" onclick="App.logout()">התנתקות</button></div>`:`<div class="form-grid"><div class="field full"><label>Project URL</label><input id="cloudUrl" dir="ltr" value="${esc(c.url||'')}"></div><div class="field full"><label>Publishable / Anon Key</label><input id="cloudKey" type="password" dir="ltr" value="${esc(c.key||'')}"></div><div class="field"><label>אימייל</label><input id="cloudEmail" type="email" dir="ltr" autocomplete="email" value="${esc(c.email||'')}"></div><div class="field"><label>סיסמה</label><input id="cloudPassword" type="password" dir="ltr" autocomplete="current-password"></div></div><div class="actions" style="margin-top:12px"><button class="btn" onclick="App.cloudLogin()">כניסה</button><button class="btn secondary" onclick="App.cloudSignup()">יצירת חשבון</button></div>`}<div class="hint" style="margin-top:12px">פרטי הפרויקט, המפתח הציבורי והאימייל נשמרים במכשיר. לאחר התחברות מוצלחת, Supabase שומר סשן מאובטח ולכן בדרך כלל לא תצטרכי להקליד שוב את הסיסמה. הסיסמה עצמה אינה נשמרת באתר או בענן.</div></div><div class="card"><h2>ייבוא מתכונים חכם</h2><div class="notice">המנתח המקומי פעיל תמיד. פונקציית Supabase בשם <strong>parse-recipe</strong> מוסיפה ניתוח AI כאשר היא מוגדרת.</div><div class="hint" style="margin-top:10px">מפתח ה־AI אינו נשמר באתר או ב־GitHub.</div></div><div class="card"><h2>גיבוי ותחזוקה</h2><div class="actions"><button class="btn secondary" onclick="App.exportData()">הורדת גיבוי</button><button class="btn ghost" onclick="document.getElementById('importFile').click()">ייבוא גיבוי</button><button class="btn danger" onclick="App.resetAll()">מחיקת כל הנתונים</button></div></div></div>`;const form=document.getElementById('settingsForm');form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);state.settings={...state.settings,businessName:f.get('businessName')||'Bakery Workspace',currency:f.get('currency')||'₪',laborRate:Number(f.get('laborRate')||0),distanceCostPerKm:Number(f.get('distanceCostPerKm')||0),ovens:Math.max(1,Math.floor(Number(f.get('ovens'))||1)),ovenTrays:Math.max(1,Math.floor(Number(f.get('ovenTrays'))||1)),workStart:f.get('workStart')||'08:00',workEnd:f.get('workEnd')||'18:00'};await persist();render()}}

/* Supabase */
function getCloud(){try{return JSON.parse(localStorage.getItem(CLOUD_KEY)||'null')}catch(e){return null}}
function hasBusinessData(x){return !!((x.recipes&&x.recipes.length)||(x.orders&&x.orders.length)||(x.inventory&&x.inventory.length)||(x.suppliers&&x.suppliers.length))}
function initCloud(){const c=getCloud();if(!c?.url||!c?.key||!window.supabase)return false;cloud.client=window.supabase.createClient(c.url,c.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'bakery-workspace-auth-v1'}});return true}
function remoteIsNewer(updatedAt){return(Date.parse(updatedAt||0)||0)>(Date.parse(state.updatedAt||0)||0)+250}
function applyRemote(data,updatedAt,show=true){if(!data)return;if(updatedAt&&!remoteIsNewer(updatedAt)&&hasBusinessData(state))return;state=migrateState({...data,updatedAt:updatedAt||data.updatedAt||new Date().toISOString()});localStorage.setItem(LS_KEY,JSON.stringify(state));if(show){setStatus('✓ התעדכן מהענן');setTimeout(()=>setStatus(''),1400)}render()}
async function cloudAuth(mode){const url=document.getElementById('cloudUrl')?.value.trim(),key=document.getElementById('cloudKey')?.value.trim(),email=document.getElementById('cloudEmail')?.value.trim(),password=document.getElementById('cloudPassword')?.value;if(!url||!key||!email||!password)return alert('יש למלא את כל פרטי החיבור');localStorage.setItem(CLOUD_KEY,JSON.stringify({url,key,email}));if(!initCloud())return alert('פרטי Supabase אינם תקינים');setStatus('מתחברת…');const res=mode==='signup'?await cloud.client.auth.signUp({email,password}):await cloud.client.auth.signInWithPassword({email,password});if(res.error){setStatus('⚠ ההתחברות נכשלה');return alert(res.error.message)}cloud.user=res.data.user;if(!cloud.user){setStatus('');return alert('נשלח אימייל אימות. אשרי אותו ואז התחברי.')}await initialCloudSync();startCloudSync();setStatus('✓ החיבור נשמר');render()}
async function initialCloudSync(){if(!cloud.user||!cloud.client)return;setStatus('מסנכרן…');const {data,error}=await cloud.client.from('bakery_os_data').select('data,updated_at').eq('user_id',cloud.user.id).maybeSingle();if(error){setStatus('⚠ שגיאת סנכרון');throw error}if(data?.data){const localHas=hasBusinessData(state),remoteHas=hasBusinessData(data.data),localTime=Date.parse(state.updatedAt||0)||0,remoteTime=Date.parse(data.updated_at||data.data.updatedAt||0)||0;if(localHas&&(!remoteHas||localTime>remoteTime+250)){await pushCloud();setStatus('✓ הנתונים מהמכשיר נשמרו בענן')}else{state=migrateState({...data.data,updatedAt:data.updated_at||data.data.updatedAt});localStorage.setItem(LS_KEY,JSON.stringify(state));setStatus('✓ נטען מהענן')}}else if(hasBusinessData(state))await pushCloud();else{state.updatedAt=new Date().toISOString();await pushCloud()}}
async function pushCloud(){if(!cloud.user||!cloud.client)return false;const stamp=state.updatedAt||new Date().toISOString();state.updatedAt=stamp;const {error}=await cloud.client.from('bakery_os_data').upsert({user_id:cloud.user.id,data:state,updated_at:stamp},{onConflict:'user_id'});if(error){console.error(error);setStatus('⚠ השמירה בענן נכשלה');return false}return true}
async function pullCloud(show=true){if(!cloud.user||!cloud.client)return;if(show)setStatus('טוען מהענן…');const {data,error}=await cloud.client.from('bakery_os_data').select('data,updated_at').eq('user_id',cloud.user.id).maybeSingle();if(error){if(show)setStatus('⚠ שגיאת טעינה');console.error(error);return}if(data?.data){if(remoteIsNewer(data.updated_at)||!hasBusinessData(state))applyRemote(data.data,data.updated_at,show);else if(show){setStatus('✓ כבר מעודכן');setTimeout(()=>setStatus(''),1200)}}}
function stopCloudSync(){if(cloud.channel&&cloud.client)cloud.client.removeChannel(cloud.channel);cloud.channel=null;if(cloud.timer)clearInterval(cloud.timer);cloud.timer=null}
function startCloudSync(){stopCloudSync();if(!cloud.user||!cloud.client)return;cloud.channel=cloud.client.channel('bakery-os-'+cloud.user.id).on('postgres_changes',{event:'*',schema:'public',table:'bakery_os_data',filter:'user_id=eq.'+cloud.user.id},payload=>{const row=payload.new;if(row?.data&&remoteIsNewer(row.updated_at))applyRemote(row.data,row.updated_at,true)}).subscribe();cloud.timer=setInterval(()=>{if(document.visibilityState==='visible')pullCloud(false)},15000)}
async function initSession(){if(!initCloud())return;const {data,error}=await cloud.client.auth.getSession();if(error){console.warn('Session restore failed',error);return}cloud.user=data?.session?.user||null;if(cloud.user){setStatus('מתחברת לענן…');await initialCloudSync();startCloudSync();setStatus('✓ מחוברת לענן');setTimeout(()=>setStatus(''),1400)}}
function exportData(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='bakery-os-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href)}
async function importData(file){try{state=migrateState(JSON.parse(await file.text()));await persist();render();alert('הנתונים יובאו')}catch(e){alert('קובץ לא תקין')}}

window.App={
  go,openPlanner,close,
  newOrder:()=>orderForm(),editOrder:x=>orderForm(state.orders.find(o=>o.id===x)),deleteOrder:async x=>{if(confirm('למחוק את ההזמנה?')){state.orders=state.orders.filter(o=>o.id!==x);await persist();render()}},addOrderItem:()=>document.getElementById('orderItems').insertAdjacentHTML('beforeend',orderRow({recipeId:'',qty:1})),
  newRecipe:()=>recipeForm(),editRecipe:x=>recipeForm(state.recipes.find(r=>r.id===x)),deleteRecipe:async x=>{if(confirm('למחוק את המתכון?')){state.recipes=state.recipes.filter(r=>r.id!==x);await persist();render()}},
  addIngredient:()=>{document.getElementById('recipeIngredients').insertAdjacentHTML('beforeend',ingredientRow({name:'',qty:'',unit:'גרם',category:'אחר'}));updateRecipeWeightPreview()},removeIngredient:b=>{b.closest('.ingredient-row').remove();updateRecipeWeightPreview()},addStep:()=>document.getElementById('recipeSteps').insertAdjacentHTML('beforeend',stepRow({text:'',daysBefore:1,time:'',durationMin:0})),
  addSubRecipe:()=>{document.getElementById('subRecipes').insertAdjacentHTML('beforeend',subRecipeCard());updateRecipeWeightPreview()},addSubIngredient:b=>{b.parentElement.querySelector('.sub-ingredients').insertAdjacentHTML('beforeend',ingredientRow({name:'',qty:'',unit:'גרם',category:'אחר'},true));updateRecipeWeightPreview()},addSubStep:b=>b.parentElement.querySelector('.sub-steps').insertAdjacentHTML('beforeend',stepRow({text:'',daysBefore:3,time:'',durationMin:0},true)),updateRecipeWeightPreview,
  weightCalc:x=>weightCalculator(state.recipes.find(r=>r.id===x)),scaleMode:(mode,button)=>{window.__scaleMode=mode;document.getElementById('scaleWeightField').hidden=mode!=='weight';document.getElementById('scaleBagsField').hidden=mode!=='bags';button.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===button));window.__updateScale?.()},
  importRecipe:importRecipeModal,analyzeRecipeImport,openPendingRecipe:()=>{const r=pendingImport;pendingImport=null;close();recipeForm(r)},filterRecipeBook,openBookRecipe,switchBookPane:(pane,button)=>{document.querySelectorAll('.book-pane').forEach(x=>x.classList.toggle('active',x.id===`book-${pane}`));button.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===button))},copyRecipe:async x=>{const r=recipe(x);try{await navigator.clipboard.writeText(recipePlainText(r));setStatus('✓ המתכון הועתק')}catch(e){alert(recipePlainText(r))}},
  toggleTask:async k=>{state.checkedTasks[k]=!state.checkedTasks[k];await persist();render()},toggleShopping:async k=>{state.checkedShopping[k]=!state.checkedShopping[k];await persist();render()},
  plannerPrev:()=>{plannerWeekOffset--;render()},plannerNext:()=>{plannerWeekOffset++;render()},plannerToday:()=>{plannerWeekOffset=0;plannerDay=dayKey(new Date());render()},setPlannerMode:m=>{plannerMode=m;render()},setPlannerDay:d=>{plannerDay=d;render()},buildPlan:async()=>{state.planOverrides={};await persist();render();setStatus('✓ התוכנית נבנתה מחדש')},newManualTask:manualTaskForm,editPlanTask,dragPlanTask:(e,key)=>{draggedTaskKey=key;e.dataTransfer.effectAllowed='move'},dropPlanTask:async(e,date)=>{e.preventDefault();const key=draggedTaskKey||e.dataTransfer.getData('text/plain');if(!key)return;state.planOverrides[key]={...(state.planOverrides[key]||{}),date};await persist();render()},deleteManualTask:async key=>{state.manualTasks=state.manualTasks.filter(t=>t.key!==key);delete state.planOverrides[key];delete state.checkedTasks[key];await persist();close();render()},
  newInventory:()=>inventoryForm(),editInventory:x=>inventoryForm(state.inventory.find(i=>i.id===x)),deleteInventory:async x=>{if(confirm('למחוק את הפריט?')){state.inventory=state.inventory.filter(i=>i.id!==x);await persist();render()}},
  newSupplier:()=>supplierForm(),editSupplier:x=>supplierForm(state.suppliers.find(s=>s.id===x)),deleteSupplier:async x=>{if(confirm('למחוק את הספק?')){state.suppliers=state.suppliers.filter(s=>s.id!==x);await persist();render()}},addPrice:()=>document.getElementById('supplierPrices').insertAdjacentHTML('beforeend',priceRow({ingredient:'',packQty:1,unit:'ק"ג',packPrice:0})),
  filterPriceCatalog,linkCatalogProduct,deletePriceImport:async x=>{if(confirm('למחוק את קובץ המחירים שיובא?')){state.priceImports=state.priceImports.filter(i=>i.id!==x);await persist();render()}},
  exportData,cloudLogin:()=>cloudAuth('login'),cloudSignup:()=>cloudAuth('signup'),pullCloud,logout:async()=>{stopCloudSync();if(cloud.client)await cloud.client.auth.signOut();cloud.user=null;setStatus('התנתקת מהענן');render()},resetAll:async()=>{if(confirm('למחוק את כל הנתונים?')){state=empty();await persist(false);render()}}
};

document.querySelectorAll('#tabs button').forEach(b=>b.onclick=()=>go(b.dataset.view));
document.getElementById('modalClose').onclick=close;document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')close()};document.getElementById('backupBtn').onclick=exportData;document.getElementById('cloudBtn').onclick=()=>go('settings');
document.getElementById('importFile').onchange=e=>{if(e.target.files[0])importData(e.target.files[0]);e.target.value=''};document.getElementById('ramiImportFile').onchange=e=>{if(e.target.files[0])importRamiFile(e.target.files[0]);e.target.value=''};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&cloud.user)pullCloud(false)});window.addEventListener('focus',()=>{if(cloud.user)pullCloud(false)});window.addEventListener('online',()=>{if(cloud.user)pullCloud(false)});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=760').then(r=>r.update()).catch(()=>{}));
initSession().finally(render);
